package main
import("context";"encoding/json";"errors";"os";"sort";"github.com/jackc/pgx/v5/pgtype";"workpal.local/workpal/server/internal/projectaccess";"workpal.local/workpal/server/internal/util";db "workpal.local/workpal/server/pkg/db/generated")
type task struct{Issue *string `json:"issue_id"`;Chat *string `json:"chat_session_id"`;Run *string `json:"autopilot_run_id"`;Context string `json:"context"`}
type fixture struct{Tasks []task;Failure string}
type queries struct{failure string;calls []any}
func uid(s *string)pgtype.UUID{if s==nil{return pgtype.UUID{}};v,e:=util.ParseUUID(*s);if e!=nil{panic(e)};return v}
func id(s string)pgtype.UUID{return uid(&s)}
func(q *queries)record(kind string,ids []pgtype.UUID)error{values:=[]string{};for _,v:=range ids{values=append(values,util.UUIDToString(v))};sort.Strings(values);q.calls=append(q.calls,map[string]any{"kind":kind,"ids":values});if q.failure==kind{return errors.New("db down")};return nil}
func(q *queries)ListIssueProjectIDs(_ context.Context,ids []pgtype.UUID)([]db.ListIssueProjectIDsRow,error){if e:=q.record("issue",ids);e!=nil{return nil,e};return []db.ListIssueProjectIDsRow{{ID:id("00000000-0000-0000-0000-000000000003"),ProjectID:id("00000000-0000-0000-0000-000000000002")}},nil}
func(q *queries)ListAutopilotRunProjectIDs(_ context.Context,ids []pgtype.UUID)([]db.ListAutopilotRunProjectIDsRow,error){if e:=q.record("run",ids);e!=nil{return nil,e};rows:=[]db.ListAutopilotRunProjectIDsRow{};for _,v:=range ids{rows=append(rows,db.ListAutopilotRunProjectIDsRow{ID:v,ProjectID:id("00000000-0000-0000-0000-000000000001")})};return rows,nil}
func main(){var fixtures []fixture;if e:=json.NewDecoder(os.Stdin).Decode(&fixtures);e!=nil{panic(e)};out:=[]any{};for _,f:=range fixtures{q:=&queries{failure:f.Failure,calls:[]any{}};tasks:=[]db.AgentTaskQueue{};for _,t:=range f.Tasks{tasks=append(tasks,db.AgentTaskQueue{IssueID:uid(t.Issue),ChatSessionID:uid(t.Chat),AutopilotRunID:uid(t.Run),Context:[]byte(t.Context)})};projects,e:=projectaccess.TasksProjects(context.Background(),q,tasks);var values [][]string;if projects!=nil{values=make([][]string,len(projects));for i,ps:=range projects{for _,p:=range ps{values[i]=append(values[i],util.UUIDToString(p))}}};message:="";if e!=nil{message=e.Error()};out=append(out,map[string]any{"projects":values,"calls":q.calls,"error":message})};json.NewEncoder(os.Stdout).Encode(out)}
